import math

def aggregate(samples):
    n = len(samples)
    times = sorted(e for _, e, _ in samples)
    def pct(p):
        return times[max(0, math.ceil(p / 100 * n) - 1)]
    start = min(t for t, _, _ in samples)
    end = max(t + e for t, e, _ in samples)
    return {
        'samples': n,
        'average': round(sum(times) / n),
        'median': pct(50),
        'p90': pct(90),
        'error_pct': round(sum(1 for *_, ok in samples if not ok) * 100 / n, 2),
        'throughput': round(n / ((end - start) / 1000), 2),
    }

