import csv, io

def failed_labels(jtl_text):
    out = {}
    for row in csv.DictReader(io.StringIO(jtl_text)):
        if row['success'].strip().lower() == 'false':
            out[row['label']] = out.get(row['label'], 0) + 1
    return out
